    def change_autoconfiguration_status(self, state, timeout=30):
        """
        Change autoconfiguration status

        :param string state: autoconfigurationState <Disable | Enable>
        :param int timeout: Timeout for the operation, defaults to 30
        :raises ValueError: Raised if provided state is not "Disable" or "Enable"
        :return: str: status "Completed" or "Failed"

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-changeAutoconfigurationStatus.html
        """

        state = state.title()
        if state not in ("Disable", "Enable"):
            raise_value_error(param="state",
                              value=str(state),
                              subpage="tutorial-changeAutoconfigurationStatus.html")

        return self._api_client.execute_procedure(name="changeAutoconfigurationStatus",
                                                  parameters={"autoconfigurationState": state},
                                                  timeout=timeout)

