    def install_certificate(self, cert_file, cert_type, cert_format, password=None, timeout=60, detailed_output=False,
                            key_pool_type=None):
        """
        Install certificate.

        :param str cert_file: Certificate file path.
        :param str cert_type: Certificate type, one of: ["BtsTrustChain", "AdditionalCa", "CBRSVendorChain",
            "CBRSAdditionalCa"]
        :param str cert_format: Certificate format, one of: ["PEM", "P12", "DER"]
        :param str password: (optional) Certificate password.
        :param int timeout: Time to wait for positive procedure result.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :param string key_pool_type: (optional) Certificate key pool type.
        :return: Union[str, dict]: operation status when detailed_output is False else full response.
        :raises: ValueError if cert_type does not meet one of the given values.
        :raises: ValueError if cert_format does not meet one of the given values.

        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-installCert.html
        """
        if cert_type not in ("BtsTrustChain", "AdditionalCa", "CBRSVendorChain", "CBRSAdditionalCa"):
            raise_value_error(param="cert_type",
                              value=str(cert_type),
                              subpage="tutorial-installCert.html")
        if cert_format not in ("PEM", "P12", "DER"):
            raise_value_error(param="cert_format",
                              value=str(cert_format),
                              subpage="tutorial-installCert.html")

        parameters = {"fileType": cert_type, "fileFormat": cert_format}
        if password:
            parameters["password"] = password
        if key_pool_type:
            parameters["keyPoolType"] = key_pool_type

        response = self._api_client.execute_customer_procedure("installCert", parameters, timeout, input_file_name=cert_file)
        return response if detailed_output else response.get(self._provided_content.request_message)

