    def configure_netconf_radio_management(self, authentication_method, id, name, password, dist_name=None, format=None,
                                           value=None, unsecure_ciphering=True, additional_name=None,
                                           additional_password=None, additional_type=None, timeout=60):
        """
        Configure Netconf radio management.

        *** DEPRECATED ***
         Please use configure_netconf_accounts.

        :param string authentication_method: One of: ['NoAuthentication', 'PublicKeyBased','DeactivationOfSSHPublicKeyValidationAtFirstConnection']
        :param string id: Unique id.
        :param string dist_name: RMOD_A distName.
        :param string name: Default account name.
        :param string password: Default account password.
        :param string format: Public key ssh server format.
        :param string value: Public key ssh server value.
        :param bool unsecure_ciphering: One of [True, False] - true by default.
        :param string additional_name: Additional account name.
        :param string additional_password: Additional account password.
        :param string additional_type: Additional account type.
        :param int timeout: Time to wait for positive procedure result.

        :return: str: Api response.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-configORUNetconfAccount.html
        """
        logging.warning('[DEPRECATION WARNING] This keyword is deprecated.'
                        ' Use configure_netconf_accounts instead')

        if authentication_method not in ('NoAuthentication', 'PublicKeyBased', 'DeactivationOfSSHPublicKeyValidationAtFirstConnection'):
            raise_value_error(param="authentication_method",
                              value=str(authentication_method),
                              subpage="tutorial-configORUNetconfAccount.html")

        accounts = {"id": id,
                    "targetDN": dist_name,
                    "defaultNetconfAccount": {
                        "defaultNetconfAccountName": name,
                        "defaultNetconfAccountPwd": password},
                    "authentifierSshServer": {
                        "publicKeySshServerFormat": format,
                        "publicKeySshServerValue": value}}

        if additional_type and additional_password and additional_type:
            additional_account = {"additionalNetconfAccount": {
                "additionalNetconfAccountName": additional_name,
                "additionalNetconfAccountPwd": additional_password,
                "additionalNetconfAccountType": additional_type}}
            accounts.update(additional_account)

        parameters = {"actUnsecCiph": unsecure_ciphering,
                      "authenticationMethodSshServer": authentication_method,
                      "accounts": [accounts]}

        return self._api_client.execute_procedure("configORUNetconfAccount", parameters, timeout)

